t\":\"#626B7A\"},\"typography\":{\"fontSize\":\"16px\",\"lineHeight\":\"1.65\"}}} --><p class=\"has-text-color\" style=\"color:#626B7A;font-size:16px;line-height:1.65\">Turn what matters into one clear intention and a manageable next step.</p><!-- /wp:paragraph --></div><!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"border\":{\"top\":{\"color\":\"#9A4935\",\"width\":\"4px\"},\"left\":{\"color\":\"#DDDDE5\",\"width\":\"1px\"}},\"spacing\":{\"padding\":{\"top\":\"28px\",\"bottom\":\"28px\",\"left\":\"36px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"border-top-color:#9A4935;border-top-width:4px;border-left-color:#DDDDE5;border-left-width:1px;padding-top:28px;padding-bottom:28px;padding-left:36px\"><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#9A4935\"},\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.12em\"}}} --><p class=\"has-text-color\" style=\"color:#9A4935;font-size:13px;font-weight:700;letter-spacing:0.12em\">03 · MOVE</p><!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"30px\",\"fontWeight\":\"600\"}}} --><h3 class=\"wp-block-heading\" style=\"font-size:30px;font-weight:600\">Go</h3><!-- /wp:heading -->\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#626B7A\"},\"typography\":{\"fontSize\":\"16px\",\"lineHeight\":\"1.65\"}}} --><p class=\"has-text-color\" style=\"color:#626B7A;font-size:16px;line-height:1.65\">Carry the plan into your day with gentle movement and useful prompts.</p><!-- /wp:paragraph --></div><!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#FFFFFF\",\"text\":\"#111827\"},\"spacing\":{\"padding\":{\"top\":\"104px\",\"right\":\"24px\",\"bottom\":\"104px\",\"left\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1180px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"color:#111827;background-color:#FFFFFF;padding-top:104px;padding-right:24px;padding-bottom:104px;padding-left:24px\"><!-- wp:columns {\"verticalAlignment\":\"bottom\",\"style\":{\"spacing\":{\"blockGap\":\"64px\"}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-bottom\"><!-- wp:column {\"verticalAlignment\":\"bottom\",\"width\":\"48%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-bottom\" style=\"flex-basis:48%\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.14em\"},\"color\":{\"text\":\"#5B5BD6\"}}} --><p class=\"has-text-color\" style=\"color:#5B5BD6;font-size:13px;font-weight:700;letter-spacing:0.14em\">DESIGNED WITH CARE</p><!-- /wp:paragraph -->\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"clamp(36px,4vw,52px)\",\"fontWeight\":\"600\",\"lineHeight\":\"1.1\",\"letterSpacing\":\"-0.035em\"},\"spacing\":{\"margin\":{\"top\":\"16px\",\"bottom\":\"0\"}}}} --><h2 class=\"wp-block-heading\" style=\"margin-top:16px;margin-bottom:0;font-size:clamp(36px,4vw,52px);font-weight:600;letter-spacing:-0.035em;line-height:1.1\">Principles you can feel in every screen.</h2><!-- /wp:heading --></div><!-- /wp:column -->\n<!-- wp:column {\"verticalAlignment\":\"bottom\",\"width\":\"52%\"} --><div class=\"wp-block-column is-vertically-aligned-bottom\" style=\"flex-basis:52%\"><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#687181\"},\"typography\":{\"fontSize\":\"18px\",\"lineHeight\":\"1.65\"},\"spacing\":{\"margin\":{\"bottom\":\"0\"}}}} --><p class=\"has-text-color\" style=\"color:#687181;margin-bottom:0;font-size:18px;line-height:1.65\">No inflated numbers or borrowed badges — just a clear product philosophy for a modern mobile ecosystem.</p><!-- /wp:paragraph --></div><!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"style\":{\"border\":{\"top\":{\"color\":\"#DADCE3\",\"width\":\"1px\"},\"bottom\":{\"color\":\"#DADCE3\",\"width\":\"1px\"}},\"spacing\":{\"padding\":{\"top\":\"34px\",\"bottom\":\"34px\"},\"margin\":{\"top\":\"64px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"border-top-color:#DADCE3;border-top-width:1px;border-bottom-color:#DADCE3;border-bottom-width:1px;margin-top:64px;padding-top:34px;padding-bottom:34px\"><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"36px\"}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column --><div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"19px\",\"fontWeight\":\"600\"}}} --><h3 class=\"wp-block-heading\" style=\"font-size:19px;font-weight:600\">Privacy-minded</h3><!-- /wp:heading --><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#687181\"},\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.55\"}}} --><p class=\"has-text-color\" style=\"color:#687181;font-size:14px;line-height:1.55\">Designed to ask only for what each experience needs.</p><!-- /wp:paragraph --></div><!-- /wp:column -->\n<!-- wp:column --><div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"19px\",\"fontWeight\":\"600\"}}} --><h3 class=\"wp-block-heading\" style=\"font-size:19px;font-weight:600\">Built for everyday travel</h3><!-- /wp:heading --><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#687181\"},\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.55\"}}} --><p class=\"has-text-color\" style=\"color:#687181;font-size:14px;line-height:1.55\">Quick to use at home, between places or on the move.</p><!-- /wp:paragraph --></div><!-- /wp:column -->\n<!-- wp:column --><div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"19px\",\"fontWeight\":\"600\"}}} --><h3 class=\"wp-block-heading\" style=\"font-size:19px;font-weight:600\">One connected ecosystem</h3><!-- /wp:heading --><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#687181\"},\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.55\"}}} --><p class=\"has-text-color\" style=\"color:#687181;font-size:14px;line-height:1.55\">A shared logic helps three focused apps work naturally together.</p><!-- /wp:paragraph --></div><!-- /wp:column -->\n<!-- wp:column --><div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"19px\",\"fontWeight\":\"600\"}}} --><h3 class=\"wp-block-heading\" style=\"font-size:19px;font-weight:600\">Designed for mobile</h3><!-- /wp:heading --><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#687181\"},\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.55\"}}} --><p class=\"has-text-color\" style=\"color:#687181;font-size:14px;line-height:1.55\">Readable, reachable and comfortable on smaller screens.</p><!-- /wp:paragraph --></div><!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#626B7A\"},\"typography\":{\"fontSize\":\"13px\",\"textAlign\":\"center\"},\"spacing\":{\"margin\":{\"top\":\"24px\"}}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#626B7A;margin-top:24px;font-size:13px\">Elunori is a portfolio concept. These trust statements describe the product design principles.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"anchor\":\"contact\",\"style\":{\"color\":{\"background\":\"#F7F5F0\"},\"spacing\":{\"padding\":{\"top\":\"88px\",\"right\":\"24px\",\"bottom\":\"88px\",\"left\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1180px\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"contact\" style=\"background-color:#F7F5F0;padding-top:44px;padding-right:24px;padding-bottom:34px;padding-left:24px\"><!-- wp:group {\"style\":{\"color\":{\"background\":\"#27276A\",\"text\":\"#FFFFFF\"},\"border\":{\"radius\":\"44px\"},\"spa