Contact) {\n      if (homeLink) homeLink.removeAttribute(\'hidden\');\n    }\n    if (isContact) protectContactForm(homeLink);\n\n    var BREAKPOINT = 1100;\n    var WHEEL_THRESHOLD = 24;\n    var GESTURE_QUIET_MS = 120;\n    var TRANSITION_FALLBACK_MS = 800;\n    var wheelDelta = 0;\n    var wheelLocked = false;\n    var lastWheelAt = 0;\n    var wheelTimer = 0;\n    var navigationTimer = 0;\n    var scrollSyncTimer = 0;\n    var resizeTimer = 0;\n    var navigationInProgress = false;\n    var activeIndex = 0;\n    var reduceMotion = window.matchMedia(\'(prefers-reduced-motion: reduce)\');\n    var sectionNavigationActive = window.matchMedia(\'(min-width: \' + BREAKPOINT + \'px)\').matches;\n\n    function usesSectionNavigation() {\n      return window.matchMedia(\'(min-width: \' + BREAKPOINT + \'px)\').matches;\n    }\n\n    function getStops() {\n      var stops = Array.prototype.slice.call(\n        document.querySelectorAll(\'main .entry-content > .wp-block-group.alignfull\')\n      ).filter(function (section) {\n        return section.getClientRects().length > 0;\n      });\n      return stops;\n    }\n\n    function fixedTopOffset() {\n      var adminBar = document.querySelector(\'#wpadminbar\');\n      if (!adminBar) return 0;\n      var position = window.getComputedStyle(adminBar).position;\n      if ([\'fixed\', \'sticky\'].indexOf(position) < 0) return 0;\n      return Math.max(0, Math.round(adminBar.getBoundingClientRect().height));\n    }\n\n    function updateGeometry() {\n      var stops = getStops();\n      if (!stops.length) return;\n      var fixedTop = fixedTopOffset();\n      var firstTop = Math.max(0, Math.round(stops[0].getBoundingClientRect().top + window.scrollY));\n      document.documentElement.style.setProperty(\'--elunori-fixed-top\', fixedTop + \'px\');\n      document.documentElement.style.setProperty(\'--elunori-first-top\', firstTop + \'px\');\n      var footer = document.querySelector(\'footer.wp-block-template-part\');\n      var finalGap = 20;\n      var footerHeight = footer ? Math.ceil(footer.getBoundingClientRect().height) : 0;\n      var finalMinimum = Math.max(0, window.innerHeight - fixedTop - footerHeight - finalGap);\n      document.documentElement.style.setProperty(\'--elunori-final-min-height\', finalMinimum + \'px\');\n      document.documentElement.classList.add(\'elunori-geometry-ready\');\n    }\n\n    function stopTop(section, index) {\n      if (index === 0) return 0;\n      var top = section.getBoundingClientRect().top + window.scrollY - fixedTopOffset();\n      var max = Math.max(0, document.documentElement.scrollHeight - window.innerHeight);\n      return Math.min(max, Math.max(0, Math.round(top)));\n    }\n\n    function currentIndex(stops) {\n      var max = Math.max(0, document.documentElement.scrollHeight - window.innerHeight);\n      if (window.scrollY <= 2) return 0;\n      if (max - window.scrollY <= 2) return stops.length - 1;\n      var offset = fixedTopOffset();\n      var current = 0;\n      var closest = Number.POSITIVE_INFINITY;\n      stops.forEach(function (section, index) {\n        var distance = Math.abs(section.getBoundingClientRect().top - offset);\n        if (distance < closest) {\n          closest = distance;\n          current = index;\n        }\n      });\n      return current;\n    }\n\n    function syncActive() {\n      var stops = getStops();\n      if (stops.length) activeIndex = currentIndex(stops);\n      updateBackButton();\n    }\n\n    function settleNavigation() {\n      if (!navigationInProgress) return;\n      navigationInProgress = false;\n      window.clearTimeout(navigationTimer);\n      syncActive();\n    }\n\n    function goToIndex(index, immediate) {\n      var stops = getStops();\n      if (!stops.length) return;\n      var next = Math.min(Math.max(index, 0), stops.length - 1);\n      activeIndex = next;\n      navigationInProgress = !immediate;\n      window.clearTimeout(navigationTimer);\n      if (!immediate) {\n        navigationTimer = window.setTimeout(settleNavigation, reduceMotion.matches ? 60 : TRANSITION_FALLBACK_MS);\n      }\n      window.scrollTo({\n        top: stopTop(stops[next], next),\n        behavior: immediate || reduceMotion.matches ? \'auto\' : \'smooth\'\n      });\n      if (immediate) syncActive();\n    }\n\n    function clearHashForPagedNavigation() {\n      if (!window.location.hash) return;\n      window.history.replaceState(null, \'\', window.location.pathname + window.location.search);\n    }\n\n    function goAdjacent(direction) {\n      var stops = getStops();\n      if (!stops.length) return;\n      clearHashForPagedNavigation();\n      var next = Math.min(Math.max(activeIndex + direction, 0), stops.length - 1);\n      goToIndex(next, false);\n    }\n\n    function scrollWithinTallSection(direction) {\n      var stops = getStops();\n      if (!stops.length) return false;\n      var section = stops[activeIndex];\n      var rect = section.getBoundingClientRect();\n      var fixedTop = fixedTopOffset();\n      var usableHeight = window.innerHeight - fixedTop;\n      if (rect.height <= usableHeight + 2) return false;\n      var documentTop = rect.top + window.scrollY;\n      var minimum = activeIndex === 0 ? 0 : documentTop - fixedTop;\n      var maximum = documentTop + rect.height - window.innerHeight;\n      var target = window.scrollY;\n      if (direction > 0) {\n        if (window.scrollY >= maximum - 2) return false;\n        target = Math.min(maximum, window.scrollY + usableHeight);\n      } else {\n        if (window.scrollY <= minimum + 2) return false;\n        target = Math.max(minimum, window.scrollY - usableHeight);\n      }\n      navigationInProgress = true;\n      window.clearTimeout(navigationTimer);\n      navigationTimer = window.setTimeout(settleNavigation, reduceMotion.matches ? 60 : TRANSITION_FALLBACK_MS);\n      window.scrollTo({ top: Math.round(target), behavior: reduceMotion.matches ? \'auto\' : \'smooth\' });\n      return true;\n    }\n\n    function goWheelDirection(direction) {\n      clearHashForPagedNavigation();\n      if (scrollWithinTallSection(direction)) return;\n      goAdjacent(direction);\n    }\n\n    function releaseWheelAfterQuiet() {\n      window.clearTimeout(wheelTimer);\n      wheelTimer = window.setTimeout(function checkQuiet() {\n        var remaining = GESTURE_QUIET_MS - (window.performance.now() - lastWheelAt);\n        if (remaining > 4) {\n          wheelTimer = window.setTimeout(checkQuiet, remaining);\n          return;\n        }\n        wheelLocked = false;\n        wheelDelta = 0;\n      }, GESTURE_QUIET_MS);\n    }\n\n    function menuIsOpen() {\n      return !!document.querySelector(\'.wp-block-navigation__responsive-container.is-menu-open\');\n    }\n\n    function isTextControl(target) {\n      if (!(target instanceof Element)) return false;\n      return !!target.closest(\'input, textarea, select, [contenteditable=\"true\"]\');\n    }\n\n    function isKeyboardControl(target) {\n      if (!(target instanceof Element)) return false;\n      return !!target.closest(\'input, textarea, select, button, a, summary, [role=\"button\"], [role=\"menuitem\"], [contenteditable=\"true\"]\');\n    }\n\n    function contactFormHasFocus() {\n      if (!isContact) return false;\n      var active = document.activeElement;\n      if (!(active instanceof Element)) return false;\n      return !!active.closest(\'.wpforms-container\');\n    }\n\n    function onWheel(event) {\n      if (!usesSectionNavigation() || menuIsOpen() || event.ctrlKey || !event.deltaY || Math.abs(event.deltaX) > Math.abs(event.deltaY) || isTextControl(event.target) || contactFormHasFocus()) return;\n\n      var now = window.performance.now();\n      var gap = lastWheelAt ? now - lastWheelAt : Number.POSITIVE_INFINITY;\n      lastWheelAt = now;\n      event.preventDefault();\n\n      if (wheelLocked) {\n        if (gap >= GESTURE_QUIET_MS) {\n          wheelLocked = false;\n          wheelDelta = 0;\n        } else {\n          releaseWheelAfterQuiet();\n          return;\n        }\n      }\n\n      var multiplier = event.deltaMode === WheelEvent.DOM_DELTA_LINE\n        ? 16\n        : event.deltaMode === WheelEvent.DOM_DELTA_PAGE\n          ? window.innerHeight\n          : 1;\n      var delta = event.deltaY * multiplier;\n      if (wheelDelta !== 0) {\n        if ((wheelDelta > 0) !== (delta > 0)) wheelDelta = 0;\n      }\n      wheelDelta += delta;\n      releaseWheelAfterQuiet();\n      if (Math.abs(wheelDelta) < WHEEL_THRESHOLD) return;\n\n      wheelLocked = true;\n      goWheelDirection(wheelDelta > 0 ? 1 : -1);\n      wheelDelta = 0;\n    }\n\n    function onKeyDown(event) {\n      if (!usesSectionNavigation() || menuIsOpen() || event.repeat || event.altKey || event.ctrlKey || event.metaKey || isKeyboardControl(event.target)) return;\n      if (event.key === \'ArrowDown\') {\n        event.preventDefault();\n        goAdjacent(1);\n      } else if (event.key === \'ArrowUp\') {\n        event.preventDefault();\n        goAdjacent(-1);\n      }\n    }\n\n    function onScroll() {\n      updateBackButton();\n      if (!usesSectionNavigation() || navigationInProgress) return;\n      window.clearTimeout(scrollSyncTimer);\n      scrollSyncTimer = window.setTimeout(syncActive, 140);\n    }\n\n    function onResize() {\n      var wasUsingSectionNavigation = sectionNavigationActive;\n      var targetIndex = activeIndex;\n      updateGeometry();\n      sectionNavigationActive = usesSectionNavigation();\n      window.clearTimeout(resizeTimer);\n      if (!sectionNavigationActive) {\n        wheelLocked = false;\n        wheelDelta = 0;\n        syncActive();\n        return;\n      }\n      if (!wasUsingSectionNavigation) {\n        syncActive();\n        targetIndex = activeIndex;\n      }\n      resizeTimer = window.setTimeout(function () {\n        updateGeometry();\n        goToIndex(targetIndex, true);\n      }, 100);\n    }\n\n    function stopForHash(hash) {\n      if (!hash || hash === \'#\') return null;\n      var target;\n      try { target = document.querySelector(hash); } catch (error) { return null; }\n      if (!target) return null;\n      if (target.matches(\'main .entry-content > .wp-block-group.alignfull\')) return target;\n      return target.closest(\'main .entry-content > .wp-block-group.alignfull\');\n    }\n\n    function onAnchorClick(event) {\n      var anchor = event.target instanceof Element ? event.target.closest(\'a[href]\') : null;\n      if (!anchor) return;\n      var url;\n      try { url = new URL(anchor.href, window.location.href); } catch (error) { return; }\n      if (url.origin !== window.location.origin || url.pathname !== window.location.pathname || !url.hash) return;\n      var stop = stopForHash(url.hash);\n      var stops = getStops();\n      var index = stop ? stops.indexOf(stop) : -1;\n      if (index < 0) return;\n      event.preventDefault();\n      if (window.location.hash !== url.hash) window.history.pushState(null, \'\', url.hash);\n      goToIndex(index, reduceMotion.matches);\n    }\n\n    function alignFromLocation(immediate) {\n      var hash = window.location.hash;\n      if (hash) {\n        var stop = stopForHash(hash);\n        var stops = getStops();\n        var index = stop ? stops.indexOf(stop) : -1;\n        if (index >= 0) {\n          goToIndex(index, true);\n          return;\n        }\n        var existingTarget;\n        try { existingTarget = document.querySelector(hash); } catch (error) { existingTarget = null; }\n        if (existingTarget) return;\n      }\n      if (navigationType === \'back_forward\') {\n        if (immediate) {\n          syncActive();\n          return;\n        }\n      }\n      window.scrollTo({ top: 0, behavior: \'auto\' });\n      activeIndex = 0;\n      updateBackButton();\n    }\n\n    function updateBackButton() {\n      if (!backButton) return;\n      var stops = getStops();\n      if (!stops.length) {\n        backButton.hidden = true;\n        return;\n      }\n      var heroEnd = stops[0].getBoundingClientRect().top + window.scrollY + stops[0].getBoundingClientRect().height;\n      var footer = document.querySelector(\'footer.wp-block-template-part\');\n      var footerVisible = footer ? footer.getBoundingClientRect().top < window.innerHeight : false;\n      backButton.classList.toggle(\'is-footer-visible\', footerVisible);\n      if (homeLink) homeLink.classList.toggle(\'is-footer-visible\', footerVisible);\n      backButton.hidden = window.scrollY + fixedTopOffset() < heroEnd - 4;\n    }\n\n    function onBackToTop() {\n      if (window.location.hash) window.history.replaceState(null, \'\', window.location.pathname + window.location.search);\n      goToIndex(0, true);\n    }\n\n    function onPopState() {\n      window.setTimeout(function () { alignFromLocation(false); }, 0);\n    }\n\n    updateGeometry();\n    activeIndex = currentIndex(getStops());\n    if (backButton) backButton.addEventListener(\'click\', onBackToTop);\n    window.addEventListener(\'wheel\', onWheel, { passive: false });\n    window.addEventListener(\'keydown\', onKeyDown);\n    window.addEventListener(\'scroll\', onScroll, { passive: true });\n    window.addEventListener(\'resize\', onResize, { passive: true });\n    window.addEventListener(\'popstate\', onPopState);\n    if (\'onscrollend\' in window) window.addEventListener(\'scrollend\', settleNavigation, { passive: true });\n    document.addEventListener(\'click\', onAnchorClick);\n\n    if (navigationType !== \'back_forward\') {\n      alignFromLocation(true);\n      window.requestAnimationFrame(function () {\n        updateGeometry();\n        alignFromLocation(true);\n      });\n      window.setTimeout(function () {\n        updateGeometry();\n        alignFromLocation(true);\n        if (\'scrollRestoration\' in window.history) window.history.scrollRestoration = \'auto\';\n      }, 140);\n    } else {\n      window.requestAnimationFrame(syncActive);\n    }\n  }\n\n  function protectContactForm(control) {\n    if (!control || !(\'IntersectionObserver\' in window)) return;\n    var form = document.querySelector(\'.nv-contact-content\') || document.querySelector(\'.wpforms-container\');\n    if (!form) return;\n    var observer = new IntersectionObserver(function (entries) {\n      var shouldSuspend = entries[0].isIntersecting;\n      control.classList.toggle(\'is-suspended\', shouldSuspend);\n    }, { threshold: 0.08 });\n    observer.observe(form);\n  }\n\n  if (document.readyState === \'loading\') {\n    document.addEventListener(\'DOMContentLoaded\', init, { once: true });\n  } else {\n    init();\n  }\n})();\n</script>\n<!-- /wp:html -->','Header','','publish','closed','closed','','header','','','2026-09-23 18:11:20','2026-09-23 16:11:20','',0,'http://novair-portfolio.local/header/',0,'wp_template_part','',0),(14,1,'2026-09-21 10:44:43','2026-09-21 10:44:43','<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#111827\",\"text\":\"#F7F5F0\"},\"spacing\":{\"padding\":{\"top\":\"64px\",\"right\":\"24px\",\"bottom\":\"32px\",\"left\":\"24px\"},\"blockGap\":\"40px\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"color:#F7F5F0;background-color:#111827;padding-top:64px;padding-right:24px;padding-bottom:32px;padding-left:24px\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"48px\"}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"45%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:45%\"><!-- wp:site-title {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"24px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.12em\"}}} /-->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#B7BDCA\"},\"typography\":{\"fontSize\":\"16px\",\"lineHeight\":\"1.6\"}}} -->\n<p class=\"has-text-color\" style=\"color:#B7BDCA;font-size:16px;line-height:1.6\">Three thoughtfully designed apps for a calmer, more intentional digital day.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"27.5%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:27.5%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"14px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.1em\",\"textTransform\":\"uppercase\"},\"color\":{\"text\":\"#8F95FF\"}}} -->\n<h3 class=\"wp-block-heading has-text-color\" style=\"color:#8F95FF;font-size:14px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase\">Navigate</h3>\n<!-- /wp:heading -->\n\n<!-- wp:navigation {\"overlayMenu\":\"never\",\"style\":{\"typography\":{\"fontSize\":\"15px\"},\"spacing\":{\"blockGap\":\"14px\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<!-- wp:navigation-link {\"label\":\"Home\",\"url\":\"/\",\"kind\":\"custom\"} /-->\n<!-- wp:navigation-link {\"label\":\"About\",\"url\":\"/about\",\"kind\":\"custom\"} /-->\n<!-- wp:navigation-link {\"label\":\"Contact\",\"url\":\"/contact\",\"kind\":\"custom\"} /-->\n<!-- /wp:navigation --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"27.5%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:27.5%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"14px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.1em\",\"textTransform\":\"uppercase\"},\"color\":{\"text\":\"#8F95FF\"}}} -->\n<h3 class=\"wp-block-heading has-text-color\" style=\"color:#8F95FF;font-size:14px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase\">Connect</h3>\n<!-- /wp:heading -->\n\n<!-- wp:navigation {\"overlayMenu\":\"never\",\"style\":{\"typography\":{\"fontSize\":\"15px\"},\"spacing\":{\"blockGap\":\"14px\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<!-- wp:navigation-link {\"label\":\"Privacy Policy\",\"url\":\"/privacy-policy\",\"kind\":\"custom\"} /-->\n<!-- wp:navigation-link {\"label\":\"Terms & Conditions\",\"url\":\"/terms\",\"kind\":\"custom\"} /-->\n<!-- /wp:navigation --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:separator {\"align\":\"wide\",\"style\":{\"color\":{\"background\":\"#303847\"}},\"className\":\"is-style-wide\"} -->\n<hr class=\"wp-block-separator alignwide has-text-color has-alpha-channel-opacity has-background is-style-wide\" style=\"background-color:#303847;color:#303847\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#8A93A3\"},\"typography\":{\"fontSize\":\"13px\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#8A93A3;font-size:13px\">© 2026 ELUNORI Digital. Concept portfolio project.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Footer','','publish','closed','closed','','footer','','','2026-09-22 09:43:02','2026-09-22 07:43:02','',0,'http://novair-portfolio.local/footer/',0,'wp_template_part','',0),(20,1,'2026-09-21 17:12:03','2026-09-21 17:12:03','<!-- wp:html -->\n<style>body.page-id-20{background:#F7F5F0}body.page-id-20 .wp-block-post-title{display:none!important}body.page-id-20 main{margin-top:0!important}body.page-id-20 main>.wp-block-group{padding-top:0!important;padding-bottom:0!important}.elunori-page h1,.elunori-page h2,.elunori-page h3{letter-spacing:-.035em}.elunori-founder{aspect-ratio:4/5;max-width:520px;margin:0 auto;overflow:hidden;border-radius:42px}.elunori-founder img{width:100%;height:100%;object-fit:cover;display:block}.elunori-founder-caption{max-width:520px;margin:14px auto 0}.elunori-value{border-top:1px solid #D8DAE2;padding:22px 0}.elunori-mission-principles{gap:0!important;padding-left:0!important;padding-right:0!important}.elunori-mission-principles>.wp-block-group{width:100%!important;max-width:none!important;margin-left:0!important;margin-right:0!important}@media(min-width:1100px){html.elunori-geometry-ready body.page-id-20 main .entry-content>.wp-block-group.alignfull{min-height:calc(100dvh - var(--elunori-fixed-top,0px))!important;box-sizing:border-box}html.elunori-geometry-ready body.page-id-20 main .entry-content>.wp-block-group.alignfull:first-of-type{min-height:calc(100dvh - var(--elunori-first-top,0px))!important}html.elunori-geometry-ready body.page-id-20 main .entry-content>.wp-block-group.alignfull:last-of-type{min-height:var(--elunori-final-min-height,auto)!important;display:flex;align-items:center}.elunori-mission-principles{display:flex;flex-direction:column;justify-content:flex-start}.elunori-mission-principles .elunori-value{padding-top:20px;padding-bottom:20px}body.page-id-20 footer.wp-block-template-part>.wp-block-group{padding-top:34px!important;padding-bottom:20px!important;gap:20px!important}body.page-id-20 footer.wp-block-template-part .wp-block-columns{margin-bottom:0}body.page-id-20 footer.wp-block-template-part hr{margin-top:0;margin-bottom:0}}@media(max-width:1099px){.elunori-mission-principles{min-height:0!important}}@media(max-width:781px){.elunori-section{padding-top:72px!important;padding-bottom:72px!important}.elunori-founder{min-height:440px}.elunori-page .wp-block-columns{gap:42px!important}}@media(max-width:480px){.elunori-section{padding-left:20px!important;padding-right:20px!important;padding-top:56px!important;padding-bottom:56px!important}.elunori-founder{min-height:360px}.elunori-page .wp-block-buttons{flex-direction:column;align-items:stretch}.elunori-page .wp-block-button,.elunori-page .wp-block-button__link{width:100%;text-align:center}}</style>\n<!-- /wp:html -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"elunori-page elunori-section\",\"style\":{\"color\":{\"background\":\"#F7F5F0\",\"text\":\"#111827\"},\"spacing\":{\"padding\":{\"top\":\"104px\",\"right\":\"24px\",\"bottom\":\"112px\",\"left\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1180px\"}} -->\n<div class=\"wp-block-group alignfull elunori-page elunori-section has-text-color has-background\" style=\"color:#111827;background-color:#F7F5F0;padding-top:104px;padding-right:24px;padding-bottom:112px;padding-left:24px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.14em\"},\"color\":{\"text\":\"#5B5BD6\"}}} -->\n<p class=\"has-text-color\" style=\"color:#5B5BD6;font-size:13px;font-weight:700;letter-spacing:0.14em\">ABOUT ELUNORI</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"clamp(46px,6vw,76px)\",\"fontWeight\":\"600\",\"lineHeight\":\"1.04\"},\"spacing\":{\"margin\":{\"top\":\"20px\",\"bottom\":\"30px\"}}}} -->\n<h1 class=\"wp-block-heading\" style=\"margin-top:20px;margin-bottom:30px;font-size:clamp(46px,6vw,76px);font-weight:600;line-height:1.04\">Designing a calmer relationship with the everyday.</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#626B7A\"},\"typography\":{\"fontSize\":\"21px\",\"lineHeight\":\"1.6\"}},\"layout\":{\"selfStretch\":\"fixed\",\"flexSize\":\"760px\"}} -->\n<p class=\"has-text-color\" style=\"color:#626B7A;font-size:21px;line-height:1.6\">Elunori is a concept product studio exploring how focus, movement and personal organisation can feel more natural on mobile.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"elunori-page elunori-section\",\"style\":{\"color\":{\"background\":\"#FFFFFF\",\"text\":\"#111827\"},\"spacing\":{\"padding\":{\"top\":\"112px\",\"right\":\"24px\",\"bottom\":\"112px\",\"left\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1180px\"}} -->\n<div class=\"wp-block-group alignfull elunori-page elunori-section has-text-color has-background\" style=\"color:#111827;background-color:#FFFFFF;padding-top:112px;padding-right:24px;padding-bottom:112px;padding-left:24px\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":\"72px\"}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"44%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:44%\"><!-- wp:image {\"id\":51,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"elunori-founder\"} -->\n<figure class=\"wp-block-image size-large elunori-founder\"><img src=\"http://novair-portfolio.local/wp-content/uploads/2026/09/elunori-about-editorial-819x1024.jpg\" alt=\"Abstract Elunori composition in violet, green and coral\" class=\"wp-image-51\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"elunori-founder-caption\",\"style\":{\"color\":{\"text\":\"#626B7A\"},\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.12em\"}}} -->\n<p class=\"elunori-founder-caption has-text-color\" style=\"color:#626B7A;font-size:12px;font-weight:700;letter-spacing:0.12em\">BRAND STUDY · FLOW, MOVE, POCKET</p><!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"56%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:56%\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.14em\"},\"color\":{\"text\":\"#5B5BD6\"}}} --><p class=\"has-text-color\" style=\"color:#5B5BD6;font-size:13px;font-weight:700;letter-spacing:0.14em\">OUR STORY</p><!-- /wp:paragraph -->\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"clamp(36px,4vw,54px)\",\"fontWeight\":\"600\",\"lineHeight\":\"1.1\"},\"spacing\":{\"margin\":{\"top\":\"18px\",\"bottom\":\"28px\"}}}} --><h2 class=\"wp-block-heading\" style=\"margin-top:18px;margin-bottom:28px;font-size:clamp(36px,4vw,54px);font-weight:600;line-height:1.1\">A small idea with room to breathe.</h2><!-- /wp:heading -->\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#626B7A\"},\"typography\":{\"fontSize\":\"18px\",\"lineHeight\":\"1.75\"}}} --><p class=\"has-text-color\" style=\"color:#626B7A;font-size:18px;line-height:1.75\">Elunori began with a simple question: can everyday digital tools feel useful without constantly asking for attention?</p><!-- /wp:paragraph -->\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#626B7A\"},\"typography\":{\"fontSize\":\"18px\",\"lineHeight\":\"1.75\"}}} --><p class=\"has-text-color\" style=\"color:#626B7A;font-size:18px;line-height:1.75\">That question became a connected family of three focused apps. Flow brings clarity to the day, Move supports gentle routines, and Pocket keeps useful thoughts close. Each product has its own purpose, while sharing the same calm visual language.</p><!-- /wp:paragraph -->\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#626B7A\"},\"typography\":{\"fontSize\":\"18px\",\"lineHeight\":\"1.75\"}}} --><p class=\"has-text-color\" style=\"color:#626B7A;font-size:18px;line-height:1.75\">Elunori is a fictional product ecosystem created to explore how calmer interfaces, clear hierarchy and thoughtful WordPress implementation can support everyday routines.</p><!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"elunori-page elunori-about-stop elunori-mission-principles\",\"style\":{\"color\":{\"background\":\"#FFFFFF\"},\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"100%\"}} -->\n<div class=\"wp-block-group alignfull elunori-page elunori-about-stop elunori-mission-principles has-background\" style=\"background-color:#FFFFFF\"><!-- wp:group {\"align\":\"full\",\"className\":\"elunori-page elunori-section elunori-mission-band\",\"style\":{\"color\":{\"background\":\"#15182B\",\"text\":\"#F7F5F0\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"right\":\"24px\",\"bottom\":\"40px\",\"left\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1180px\"}} -->\n<div class=\"wp-block-group alignfull elunori-page elunori-section elunori-mission-band has-text-color has-background\" style=\"color:#F7F5F0;background-color:#15182B;padding-top:40px;padding-right:24px;padding-bottom:40px;padding-left:24px\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":\"72px\"}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"38%\"} --><div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:38%\"><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#A8A8FF\"},\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.14em\"}}} --><p class=\"has-text-color\" style=\"color:#A8A8FF;font-size:13px;font-weight:700;letter-spacing:0.14em\">OUR MISSION</p><!-- /wp:paragraph --><!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"clamp(38px,4.5vw,58px)\",\"fontWeight\":\"600\",\"lineHeight\":\"1.08\"},\"spacing\":{\"margin\":{\"top\":\"18px\",\"bottom\":\"0\"}}}} --><h2 class=\"wp-block-heading\" style=\"margin-top:18px;margin-bottom:0;font-size:clamp(38px,4.5vw,58px);font-weight:600;line-height:1.08\">Make useful technology feel lighter.</h2><!-- /wp:heading --></div><!-- /wp:column -->\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"62%\"} --><div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:62%\"><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#C7CAD7\"},\"typography\":{\"fontSize\":\"21px\",\"lineHeight\":\"1.7\"}}} --><p class=\"has-text-color\" style=\"color:#C7CAD7;font-size:21px;line-height:1.7\">We imagine mobile products that respect time, reduce friction and help people move through ordinary moments with more intention.</p><!-- /wp:paragraph --></div><!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"elunori-page elunori-section elunori-principles-band\",\"style\":{\"color\":{\"background\":\"#FFFFFF\",\"text\":\"#111827\"},\"spacing\":{\"padding\":{\"top\":\"44px\",\"right\":\"24px\",\"bottom\":\"72px\",\"left\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1180px\"}} -->\n<div class=\"wp-block-group alignfull elunori-page elunori-section elunori-principles-band has-text-color has-background\" style=\"color:#111827;background-color:#FFFFFF;padding-top:44px;padding-right:24px;padding-bottom:72px;padding-left:24px\"><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"72px\"}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"36%\"} --><div class=\"wp-block-column\" style=\"flex-basis:36%\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.14em\"},\"color\":{\"text\":\"#5B5BD6\"}}} --><p class=\"has-text-color\" style=\"color:#5B5BD6;font-size:13px;font-weight:700;letter-spacing:0.14em\">PRINCIPLES</p><!-- /wp:paragraph --><!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"clamp(36px,4vw,52px)\",\"fontWeight\":\"600\",\"lineHeight\":\"1.1\"}}} --><h2 class=\"wp-block-heading\" style=\"font-size:clamp(36px,4vw,52px);font-weight:600;line-height:1.1\">How we choose what belongs.</h2><!-- /wp:heading --></div><!-- /wp:column -->\n<!-- wp:column {\"width\":\"64%\"} --><div class=\"wp-block-column\" style=\"flex-basis:64%\"><!-- wp:group {\"className\":\"elunori-value\",\"layout\":{\"type\":\"constrained\"}} --><div class=\"wp-block-group elunori-value\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"26px\",\"fontWeight\":\"600\"}}} --><h3 class=\"wp-block-heading\" style=\"font-size:26px;font-weight:600\">Calm by default</h3><!-- /wp:heading --><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#687181\"},\"typography\":{\"fontSize\":\"17px\",\"lineHeight\":\"1.65\"}}} --><p class=\"has-text-color\" style=\"color:#687181;font-size:17px;line-height:1.65\">Interfaces should guide quietly, with clear choices and generous space.</p><!-- /wp:paragraph --></div><!-- /wp:group -->\n<!-- wp:group {\"className\":\"elunori-value\",\"layout\":{\"type\":\"constrained\"}} --><div class=\"wp-block-group elunori-value\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"26px\",\"fontWeight\":\"600\"}}} --><h3 class=\"wp-block-heading\" style=\"font-size:26px;font-weight:600\">Useful before impressive</h3><!-- /wp:heading --><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#687181\"},\"typography\":{\"fontSize\":\"17px\",\"lineHeight\":\"1.65\"}}} --><p class=\"has-text-color\" style=\"color:#687181;font-size:17px;line-height:1.65\">Every feature needs a clear role in the day, not a place on a checklist.</p><!-- /wp:paragraph --></div><!-- /wp:group -->\n<!-- wp:group {\"className\":\"elunori-value\",\"layout\":{\"type\":\"constrained\"}} --><div class=\"wp-block-group elunori-value\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"26px\",\"fontWeight\":\"600\"}}} --><h3 class=\"wp-block-heading\" style=\"font-size:26px;font-weight:600\">Consistent, not identical</h3><!-- /wp:heading --><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#687181\"},\"typography\":{\"fontSize\":\"17px\",\"lineHeight\":\"1.65\"}}} --><p class=\"has-text-color\" style=\"color:#687181;font-size:17px;line-height:1.65\">Each app keeps its character while contributing to one familiar ecosystem.</p><!-- /wp:paragraph --></div><!-- /wp:group --></div><!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"align\":\"full\",\"className\":\"elunori-page elunori-section\",\"style\":{\"color\":{\"background\":\"#F7F5F0\"},\"spacing\":{\"padding\":{\"top\":\"88px\",\"right\":\"24px\",\"bottom\":\"88px\",\"left\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1180px\"}} -->\n<div class=\"wp-block-group alignfull elunori-page elunori-section has-background\" style=\"background-color:#F7F5F0;padding-top:88px;padding-right:24px;padding-bottom:88px;padding-left:24px\"><!-- wp:group {\"style\":{\"color\":{\"background\":\"#27276A\",\"text\":\"#FFFFFF\"},\"border\":{\"radius\":\"42px\"},\"spacing\":{\"padding\":{\"top\":\"70px\",\"right\":\"40px\",\"bottom\":\"70px\",\"left\":\"40px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"820px\"}} -->\n<div class=\"wp-block-group has-text-color has-background\" style=\"border-radius:42px;color:#FFFFFF;background-color:#27276A;padding-top:70px;padding-right:40px;padding-bottom:70px;padding-left:40px\"><!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"clamp(38px,5vw,60px)\",\"fontWeight\":\"600\",\"lineHeight\":\"1.08\",\"textAlign\":\"center\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"24px\"}}}} --><h2 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:0;margin-bottom:24px;font-size:clamp(38px,5vw,60px);font-weight:600;line-height:1.08\">See the idea in motion.</h2><!-- /wp:heading -->\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#D9DAF4\"},\"typography\":{\"fontSize\":\"18px\",\"lineHeight\":\"1.65\",\"textAlign\":\"center\"},\"spacing\":{\"margin\":{\"bottom\":\"34px\"}}}} --><p class=\"has-text-align-center has-text-color\" style=\"color:#D9DAF4;margin-bottom:34px;font-size:18px;line-height:1.65\">Explore the three apps or start a conversation about the Elunori concept.</p><!-- /wp:paragraph -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"},\"style\":{\"spacing\":{\"blockGap\":\"14px\"}}} --><div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"color\":{\"background\":\"#FFFFFF\",\"text\":\"#27276A\"},\"border\":{\"radius\":\"999px\"}}} --><div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-color has-background wp-element-button\" href=\"/#apps\" style=\"border-radius:999px;color:#27276A;background-color:#FFFFFF\">Explore the apps</a></div><!-- /wp:button --><!-- wp:button {\"className\":\"is-style-outline\",\"style\":{\"color\":{\"text\":\"#FFFFFF\"},\"border\":{\"color\":\"#8587D8\",\"radius\":\"999px\"}}} --><div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link has-text-color has-border-color wp-element-button\" href=\"/contact\" style=\"border-color:#8587D8;border-radius:999px;color:#FFFFFF\">Contact Elunori</a></div><!-- /wp:button --></div><!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','About','','publish','closed','closed','','about','','','2026-09-23 11:28:34','2026-09-23 09:28:34','',0,'http://novair-portfolio.local/?page_id=20',0,'page','',0),(22,1,'2026-09-21 17:13:27','2026-09-21 17:13:27','<!-- wp:group {\"align\":\"full\",\"className\":\"nv-stage4-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull nv-stage4-full\">\n<!-- wp:html -->\n<style>body.page-id-22 .wp-block-post-title{display:none}.nv-legal{width:100%;max-width:none;margin:0}.nv-legal{background:#fff;color:#111827;overflow:hidden}.nv-legal *{box-sizing:border-box}.nv-legal-hero{background:#F7F5F0;padding:96px 24px 88px}.nv-legal-hero>div,.nv-legal-body>div{max-width:860px;margin:auto}.nv-kicker{color:#5B5BD6;font-size:13px;font-weight:700;letter-spacing:.14em}.nv-legal h1{font-size:clamp(46px,6vw,72px);line-height:1.04;letter-spacing:-.045em;margin:18px 0 24px;font-weight:600}.nv-lead{font-size:20px;line-height:1.65;color:#626B7A;max-width:720px}.nv-meta{margin-top:34px;padding-top:24px;border-top:1px solid #D8DAE2;color:#7A8190;font-size:13px}.nv-legal-body{padding:88px 24px 112px}.nv-notice{background:#F3F2FF;border-radius:24px;padding:26px 30px;margin-bottom:56px;color:#34345E}.nv-legal h2{font-size:30px;line-height:1.2;letter-spacing:-.025em;margin:48px 0 16px;font-weight:600}.nv-legal p,.nv-legal li{font-size:17px;line-height:1.75;color:#596272}.nv-legal a{color:#27276A}.nv-back{margin-top:64px;padding-top:32px;border-top:1px solid #D8DAE2}.nv-back a{display:inline-block;background:#27276A;color:#fff;text-decoration:none;border-radius:999px;padding:14px 24px;font-weight:600}@media(max-width:480px){.nv-legal-hero{padding:64px 20px 60px}.nv-legal-body{padding:56px 20px 72px}.nv-legal h1{font-size:44px}.nv-lead{font-size:18px}.nv-legal h2{font-size:26px;margin-top:38px}.nv-notice{padding:22px}}</style>\n<section class=\"nv-legal\"><header class=\"nv-legal-hero\"><div><div class=\"nv-kicker\">LEGAL · DEMO DOCUMENT</div><h1>Privacy Policy</h1><p class=\"nv-lead\">A clear overview of how information would be handled on the Elunori website.</p><div class=\"nv-meta\">Last updated: 21 September 2026 · Portfolio demonstration</div></div></header><main class=\"nv-legal-body\"><div><aside class=\"nv-notice\"><strong>Important:</strong> Elunori is a fictional portfolio brand. This page is demonstration content, not legal advice or a guarantee of compliance. It should be reviewed and adapted by a qualified professional before any public launch.</aside><h2>1. Overview</h2><p>This policy explains what information the Elunori website may collect, why it may be used, and the choices available to visitors. The current site runs locally as a portfolio project and is not collecting public visitor data.</p><h2>2. Information you provide</h2><p>If you use the contact form, you may provide your name, email address, subject and message. These details are used only to understand and respond to your enquiry.</p><h2>3. Information collected automatically</h2><p>A production website may record basic technical information such as browser type, device type, approximate location, referring page and server logs. No analytics or advertising platform is connected to this local demonstration.</p><h2>4. How information may be used</h2><ul><li>To respond to messages and support requests.</li><li>To maintain the security and reliability of the website.</li><li>To understand general site performance if privacy-conscious analytics are added later.</li><li>To meet applicable legal obligations.</li></ul><h2>5. Cookies and local storage</h2><p>The current portfolio build does not intentionally use marketing cookies. WordPress or essential site features may use technical cookies for administration, security or preferences. Any future analytics or marketing cookies should be documented and, where required, presented with appropriate consent controls.</p><h2>6. Third-party services</h2><p>No analytics, advertising, payment or social tracking services are connected at this stage. A production launch may add hosting, email delivery and spam-prevention providers. Their names, purposes and policies should be listed here before launch.</p><h2>7. Retention and security</h2><p>Contact messages should be kept only as long as needed to answer the enquiry or meet a legitimate operational requirement. Reasonable technical and organisational safeguards should be used, but no online service can guarantee absolute security.</p><h2>8. Your choices</h2><p>Depending on applicable law, visitors may be able to request access, correction or deletion of personal information, or object to certain processing. A production contact address for privacy requests should be published before launch.</p><h2>9. Children</h2><p>This website is not intended to knowingly collect personal information from children. Any future app-specific age requirements should be described in the relevant product policy.</p><h2>10. Changes to this policy</h2><p>This demonstration policy may be updated as the project changes. A public version should include an effective date and a practical way to notify users of material changes.</p><h2>11. Contact</h2><p>For this portfolio demonstration, use the <a href=\"/contact\">Contact page</a>. A verified business identity, postal address and privacy email must be added before production release.</p><div class=\"nv-back\"><a href=\"/\">Back to Home</a></div></div></main></section>\n<!-- /wp:html -->\n</div>\n<!-- /wp:group -->','Privacy Policy','','publish','closed','closed','','privacy-policy','','',