:border-color .2s,box-shadow .2s,background .2s}.nv-contact-form input[type=text],.nv-contact-form input[type=email]{height:50px!important}.nv-contact-form textarea{height:132px!important;min-height:132px!important;resize:vertical}.nv-contact-form input:focus,.nv-contact-form textarea:focus{outline:none!important;border-color:#5B5BD6!important;background:#fff!important;box-shadow:0 0 0 4px rgba(91,91,214,.13)!important}.nv-contact-form .wpforms-submit{min-height:52px!important;border:0!important;border-radius:999px!important;background:#27276A!important;color:#fff!important;font-size:15px!important;font-weight:700!important;padding:14px 28px!important;cursor:pointer!important}.nv-contact-form .wpforms-submit:hover{background:#1E1E56!important}.nv-contact-form .wpforms-submit:focus{outline:3px solid rgba(91,91,214,.28)!important;outline-offset:3px!important}.nv-contact-form .wpforms-error{color:#A62B35!important}.nv-contact-form label.wpforms-error{font-size:13px!important;margin-top:7px!important}.nv-contact-form .wpforms-confirmation-container-full{margin:0!important;border:0!important;border-radius:20px!important;background:#E9F6EF!important;color:#173D2C!important;padding:24px!important}.nv-contact-form .wpforms-confirmation-container-full p{margin:0 0 8px}.nv-contact-form .wpforms-confirmation-container-full p:last-child{margin-bottom:0}.nv-contact-form .wpforms-field-hp{position:absolute!important;left:-9999px!important}.nv-contact-required{font-size:13px;color:#626B7A;margin:14px 0 0}.nv-contact-back{margin-top:24px}.nv-contact-back a{color:#27276A;font-weight:700;text-decoration:none}.nv-contact-back a:hover{text-decoration:underline}@media(min-width:1100px){.nv-contact-panel{padding-top:24px;padding-bottom:24px}html.elunori-geometry-ready body.page-id-28 main .entry-content>.wp-block-group.alignfull{min-height:calc(100dvh - var(--elunori-fixed-top,0px))!important;box-sizing:border-box}html.elunori-geometry-ready body.page-id-28 main .entry-content>.wp-block-